 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            if r1-r0 == 2 and c1-c0 == 2:
                obj = [row[c0:c1+1] for row in grid[r0:r1+1]]
                if all(v != 0 for row in obj for v in row):
                    components.append(obj)
    for obj in components:
        if len({v for row in obj for v in row}) == 3:
            return obj
    raise ValueError('No 3x3 three-color object found')
